SELECT "symbol", "issue", "status", "name", "exchangeid", "sk_companyid", "sharesoutstanding", "firsttrade", "firsttradeonexchange", "dividend", "iscurrent", "batchid", "effectivedate", "enddate", CAST(ROW_NUMBER() OVER (ORDER BY symbol, effectivedate) AS INT) AS "sk_securityid" FROM (SELECT TRY_CAST((sec.Symbol) AS TEXT) AS "symbol", TRY_CAST((CAST(sec.IssueType AS TEXT)) AS TEXT) AS "issue", TRY_CAST((CAST(sec.Status AS TEXT)) AS TEXT) AS "status", TRY_CAST((CAST(sec.Name AS TEXT)) AS TEXT) AS "name", TRY_CAST((CAST(sec.ExID AS TEXT)) AS TEXT) AS "exchangeid", TRY_CAST((CAST(HASH(sec.CoNameOrCIK) % 2147483648 AS INT)) AS INT) AS "sk_companyid", TRY_CAST((CAST(sec.ShOut AS INT)) AS INT) AS "sharesoutstanding", TRY_CAST((TRY_CAST(SUBSTRING(sec.FirstTradeDate, 1, 4) || '-' || SUBSTRING(sec.FirstTradeDate, 5, 2) || '-' || SUBSTRING(sec.FirstTradeDate, 7, 2) AS DATE)) AS DATE) AS "firsttrade", TRY_CAST((CAST(STRPTIME(sec.FirstTradeExchg, '%Y%m%d') AS DATE)) AS DATE) AS "firsttradeonexchange", TRY_CAST((CAST(CAST(sec.Dividend AS DOUBLE) AS INT)) AS INT) AS "dividend", CAST(NULL AS BOOLEAN) AS "iscurrent", TRY_CAST((CAST(NULL AS DECIMAL(5))) AS DECIMAL(5)) AS "batchid", TRY_CAST((MAKE_DATE(CAST(SUBSTRING(sec.PTS, 1, 4) AS INT), CAST(SUBSTRING(sec.PTS, 5, 2) AS INT), CAST(SUBSTRING(sec.PTS, 7, 2) AS INT))) AS DATE) AS "effectivedate", TRY_CAST((CAST('9999-12-31' AS DATE)) AS DATE) AS "enddate" FROM "Source"."FinwireSEC" AS sec LEFT JOIN "Source"."StatusType" AS st ON sec.Status = st.ST_ID);
